-- 1. TABELA DE FILMES (TB_CP5_FILMES)
BEGIN
   EXECUTE IMMEDIATE '
   CREATE TABLE "TB_CP5_FILMES" (
       "Id" NUMBER(10) GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL,
       "Titulo" NVARCHAR2(150) NOT NULL,
       "Sinopse" NVARCHAR2(1000),
       "Genero" NVARCHAR2(60) NOT NULL,
       "AnoLancamento" NUMBER(10) NOT NULL,
       "NotaImdb" NUMBER(3,1) NOT NULL,
       "DuracaoMinutos" NUMBER(10) NOT NULL,
       "PosterUrl" NVARCHAR2(500),
       "DataCadastro" TIMESTAMP(7) NOT NULL,
       "DataAtualizacao" TIMESTAMP(7),
       CONSTRAINT "PK_TB_CP5_FILMES" PRIMARY KEY ("Id")
   )';
EXCEPTION
   WHEN OTHERS THEN
      IF SQLCODE != -955 THEN
         RAISE;
      END IF;
END;
/

-- 2. TABELA DE AVALIAÇÕES (TB_CP5_AVALIACOES)
BEGIN
   EXECUTE IMMEDIATE '
   CREATE TABLE "TB_CP5_AVALIACOES" (
       "Id" NUMBER(10) GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL,
       "FilmeId" NUMBER(10) NOT NULL,
       "Usuario" NVARCHAR2(80) NOT NULL,
       "Comentario" NVARCHAR2(500) NOT NULL,
       "Nota" NUMBER(10) NOT NULL,
       "DataAvaliacao" TIMESTAMP(7) NOT NULL,
       CONSTRAINT "PK_TB_CP5_AVALIACOES" PRIMARY KEY ("Id"),
       CONSTRAINT "FK_TB_CP5_AVALIACOES_FILMES" 
           FOREIGN KEY ("FilmeId") REFERENCES "TB_CP5_FILMES" ("Id") ON DELETE CASCADE
   )';
EXCEPTION
   WHEN OTHERS THEN
      IF SQLCODE != -955 THEN
         RAISE;
      END IF;
END;
/

-- 3. TABELA DE USUÁRIOS E AUTENTICAÇÃO (TB_CP5_USERS)
BEGIN
   EXECUTE IMMEDIATE '
   CREATE TABLE "TB_CP5_USERS" (
       "Id" NUMBER(10) GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL,
       "Username" NVARCHAR2(50) NOT NULL,
       "PasswordHash" NVARCHAR2(200) NOT NULL,
       "Nome" NVARCHAR2(100) NOT NULL,
       "Role" NVARCHAR2(30) NOT NULL,
       "DataCriacao" TIMESTAMP(7) NOT NULL,
       CONSTRAINT "PK_TB_CP5_USERS" PRIMARY KEY ("Id")
   )';
EXCEPTION
   WHEN OTHERS THEN
      IF SQLCODE != -955 THEN
         RAISE;
      END IF;
END;
/

-- 4. ÍNDICES DE OTIMIZAÇÃO DE PERFORMANCE (CRITÉRIO OBRIGATÓRIO DO CP5)
BEGIN
   EXECUTE IMMEDIATE 'CREATE INDEX "IX_TB_CP5_FILMES_TITULO" ON "TB_CP5_FILMES" ("Titulo")';
EXCEPTION WHEN OTHERS THEN IF SQLCODE != -955 AND SQLCODE != -1408 THEN NULL; END IF;
END;
/

BEGIN
   EXECUTE IMMEDIATE 'CREATE INDEX "IX_TB_CP5_FILMES_GENERO" ON "TB_CP5_FILMES" ("Genero")';
EXCEPTION WHEN OTHERS THEN IF SQLCODE != -955 AND SQLCODE != -1408 THEN NULL; END IF;
END;
/

BEGIN
   EXECUTE IMMEDIATE 'CREATE INDEX "IX_TB_CP5_FILMES_TIT_ANO" ON "TB_CP5_FILMES" ("Titulo", "AnoLancamento")';
EXCEPTION WHEN OTHERS THEN IF SQLCODE != -955 AND SQLCODE != -1408 THEN NULL; END IF;
END;
/

BEGIN
   EXECUTE IMMEDIATE 'CREATE INDEX "IX_TB_CP5_AVALIACOES_FILMEID" ON "TB_CP5_AVALIACOES" ("FilmeId")';
EXCEPTION WHEN OTHERS THEN IF SQLCODE != -955 AND SQLCODE != -1408 THEN NULL; END IF;
END;
/

BEGIN
   EXECUTE IMMEDIATE 'CREATE INDEX "IX_TB_CP5_AVALIACOES_USUARIO" ON "TB_CP5_AVALIACOES" ("Usuario")';
EXCEPTION WHEN OTHERS THEN IF SQLCODE != -955 AND SQLCODE != -1408 THEN NULL; END IF;
END;
/

BEGIN
   EXECUTE IMMEDIATE 'CREATE UNIQUE INDEX "IX_TB_CP5_USERS_USERNAME" ON "TB_CP5_USERS" ("Username")';
EXCEPTION WHEN OTHERS THEN IF SQLCODE != -955 AND SQLCODE != -1408 THEN NULL; END IF;
END;
/

